use std::fs;
use std::io::{self, Read, BufRead};
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Instant;
use std::thread;

mod zip_parser;
mod zipcrypto;
mod aes_zip;
mod password_gen;
mod args;

use zip_parser::{parse_zip, ZipEntryInfo, EncryptionType};
use password_gen::PasswordGenerator;
use args::Args;

fn format_duration(d: std::time::Duration) -> String {
    let total_ns = d.as_nanos();

    let secs = total_ns / 1_000_000_000;
    let rem = total_ns % 1_000_000_000;
    let ms = rem / 1_000_000;
    let rem = rem % 1_000_000;
    let us = rem / 1_000;
    let ns = rem % 1_000;

    let mut parts = Vec::new();
    if secs > 0 { parts.push(format!("{}s", secs)); }
    if ms > 0 { parts.push(format!("{}ms", ms)); }
    if us > 0 { parts.push(format!("{}us", us)); }
    if ns > 0 { parts.push(format!("{}ns", ns)); }
    if parts.is_empty() { parts.push("0ns".to_string()); }

    parts.join(" ")
}

fn check_password(entry: &ZipEntryInfo, password: &[u8]) -> bool {
    match &entry.encryption {
        EncryptionType::ZipCrypto { crc32, mod_time_byte, use_mod_time } => {
            zipcrypto::check_password(password, &entry.encrypted_data[..12], *crc32, *mod_time_byte, *use_mod_time)
        }
        EncryptionType::AesWinzip { aes_strength, salt, pwd_verifier } => {
            aes_zip::check_password(password, salt, pwd_verifier, *aes_strength)
        }
    }
}

fn run_dictionary_attack(
    entry: Arc<ZipEntryInfo>,
    dict_path: &str,
    num_workers: usize,
) -> Option<String> {
    let file = match fs::File::open(dict_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("CLI argument error - \"'passwordDictionary' error: {}\"", e);
            std::process::exit(1);
        }
    };

    let reader = io::BufReader::new(file);
    let passwords: Vec<String> = reader.lines()
        .filter_map(|l| l.ok())
        .collect();

    let found = Arc::new(Mutex::new(None::<String>));
    let stop = Arc::new(AtomicBool::new(false));

    let chunk_size = (passwords.len() + num_workers - 1) / num_workers;

    let mut handles = Vec::new();

    for chunk in passwords.chunks(chunk_size) {
        let chunk = chunk.to_vec();
        let entry = entry.clone();
        let found = found.clone();
        let stop = stop.clone();

        let handle = thread::spawn(move || {
            for password in chunk {
                if stop.load(Ordering::Relaxed) {
                    break;
                }
                if check_password(&entry, password.as_bytes()) {
                    let mut f = found.lock().unwrap();
                    *f = Some(password);
                    stop.store(true, Ordering::Relaxed);
                    break;
                }
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let result = found.lock().unwrap().take();
    result
}

fn run_brute_force_attack(
    entry: Arc<ZipEntryInfo>,
    charset: Vec<u8>,
    min_len: usize,
    max_len: usize,
    starting_password: Option<Vec<u8>>,
    num_workers: usize,
) -> Option<String> {
    let found = Arc::new(Mutex::new(None::<String>));
    let stop = Arc::new(AtomicBool::new(false));

    // Determine starting length and starting indices
    let (start_len, start_indices) = if let Some(ref sp) = starting_password {
        let len = sp.len();
        let mut indices = vec![0usize; len];
        for (i, &b) in sp.iter().enumerate() {
            let pos = charset.iter().position(|&c| c == b).unwrap();
            indices[i] = pos;
        }
        (len, indices)
    } else {
        (min_len, vec![0usize; min_len])
    };

    // We need to distribute work across workers
    // Strategy: each worker handles a range of passwords
    // For simplicity, we'll use a shared work queue approach

    // Actually, let's use a simpler approach: pre-generate all starting points
    // for each worker based on the first character position

    // Better: use a shared atomic counter approach
    // Or: split by first-level enumeration

    let charset_arc = Arc::new(charset);
    let entry_arc = entry;

    // Simple approach: single-threaded for now, then add threading
    // Actually let's implement a proper multi-threaded version

    // We'll use a channel-based approach or shared counter
    // For compatibility, let's use a mutex-protected generator

    let generator = Arc::new(Mutex::new(
        PasswordGenerator::new(
            charset_arc.as_ref().clone(),
            min_len,
            max_len,
            start_len,
            start_indices,
        )
    ));

    let mut handles = Vec::new();

    for _ in 0..num_workers {
        let generator = generator.clone();
        let entry = entry_arc.clone();
        let found = found.clone();
        let stop = stop.clone();

        let handle = thread::spawn(move || {
            const BATCH_SIZE: usize = 1000;
            loop {
                if stop.load(Ordering::Relaxed) {
                    break;
                }

                // Get a batch of passwords
                let batch: Vec<Vec<u8>> = {
                    let mut gen = generator.lock().unwrap();
                    let mut batch = Vec::with_capacity(BATCH_SIZE);
                    for _ in 0..BATCH_SIZE {
                        match gen.next() {
                            Some(p) => batch.push(p),
                            None => break,
                        }
                    }
                    batch
                };

                if batch.is_empty() {
                    break;
                }

                for password in batch {
                    if stop.load(Ordering::Relaxed) {
                        return;
                    }
                    if check_password(&entry, &password) {
                        let pw_str = String::from_utf8_lossy(&password).to_string();
                        let mut f = found.lock().unwrap();
                        *f = Some(pw_str);
                        stop.store(true, Ordering::Relaxed);
                        return;
                    }
                }
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let result = found.lock().unwrap().take();
    result
}

fn main() {
    let start_time = Instant::now();

    let args = match args::parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    // Validate input file exists
    if !std::path::Path::new(&args.input_file).exists() {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        std::process::exit(1);
    }

    // Parse the zip file
    let zip_data = match fs::read(&args.input_file) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Invalid zip file error - {}", e);
            std::process::exit(1);
        }
    };

    let entry = match parse_zip(&zip_data, args.file_number) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("Invalid zip file error - {}", e);
            std::process::exit(1);
        }
    };

    let entry_arc = Arc::new(entry);

    let num_workers = args.workers;

    let found = if let Some(dict_path) = &args.password_dictionary {
        run_dictionary_attack(entry_arc, dict_path, num_workers)
    } else {
        let charset = args.charset;
        let min_len = args.min_password_len;
        let max_len = args.max_password_len;
        let starting = args.starting_password;
        run_brute_force_attack(entry_arc, charset, min_len, max_len, starting, num_workers)
    };

    let elapsed = start_time.elapsed();
    println!("Time elapsed: {}", format_duration(elapsed));

    if let Some(password) = found {
        println!("Password found:{}", password);
    } else {
        println!("Password not found");
    }
}
