use std::num::ParseIntError;

#[derive(Debug)]
pub struct Args {
    pub input_file: String,
    pub workers: usize,
    pub password_dictionary: Option<String>,
    pub charset: Vec<u8>,
    pub charset_file: Option<String>,
    pub min_password_len: usize,
    pub max_password_len: usize,
    pub file_number: usize,
    pub starting_password: Option<Vec<u8>>,
}

pub fn parse_args() -> Result<Args, String> {
    let raw_args: Vec<String> = std::env::args().collect();

    if raw_args.len() == 1 {
        print_help(&raw_args[0]);
        std::process::exit(0);
    }

    // Check for --help or -h
    if raw_args.iter().any(|a| a == "--help" || a == "-h") {
        print_help(&raw_args[0]);
        std::process::exit(0);
    }

    // Check for --version or -V
    if raw_args.iter().any(|a| a == "--version" || a == "-V") {
        println!("zip-password-finder 0.10.3");
        std::process::exit(0);
    }

    let mut input_file: Option<String> = None;
    let mut workers: Option<usize> = None;
    let mut password_dictionary: Option<String> = None;
    let mut charset_str: Option<String> = None;
    let mut charset_file: Option<String> = None;
    let mut min_password_len: Option<usize> = None;
    let mut max_password_len: Option<usize> = None;
    let mut file_number: Option<usize> = None;
    let mut starting_password: Option<String> = None;

    let mut i = 1;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        match arg.as_str() {
            "-i" | "--inputFile" => {
                i += 1;
                input_file = Some(get_arg_value(&raw_args, i, "--inputFile")?);
            }
            "-w" | "--workers" => {
                i += 1;
                let val = get_arg_value(&raw_args, i, "--workers")?;
                workers = Some(parse_usize(&val, "workers")?);
            }
            "-p" | "--passwordDictionary" => {
                i += 1;
                password_dictionary = Some(get_arg_value(&raw_args, i, "--passwordDictionary")?);
            }
            "-c" | "--charset" => {
                i += 1;
                charset_str = Some(get_arg_value(&raw_args, i, "--charset")?);
            }
            "--charsetFile" => {
                i += 1;
                charset_file = Some(get_arg_value(&raw_args, i, "--charsetFile")?);
            }
            "--minPasswordLen" => {
                i += 1;
                let val = get_arg_value(&raw_args, i, "--minPasswordLen")?;
                min_password_len = Some(parse_usize(&val, "minPasswordLen")?);
            }
            "--maxPasswordLen" => {
                i += 1;
                let val = get_arg_value(&raw_args, i, "--maxPasswordLen")?;
                max_password_len = Some(parse_usize(&val, "maxPasswordLen")?);
            }
            "--fileNumber" => {
                i += 1;
                let val = get_arg_value(&raw_args, i, "--fileNumber")?;
                file_number = Some(parse_usize(&val, "fileNumber")?);
            }
            "-s" | "--startingPassword" => {
                i += 1;
                starting_password = Some(get_arg_value(&raw_args, i, "--startingPassword")?);
            }
            _ => {
                return Err(format!("error: unrecognized argument '{}'", arg));
            }
        }
        i += 1;
    }

    // Validate required args
    let input_file = input_file.ok_or_else(|| {
        "error: the following required arguments were not provided:\n  --inputFile <inputFile>".to_string()
    })?;

    // Workers default to number of CPUs
    let workers = if let Some(w) = workers {
        if w == 0 {
            return Err("CLI argument error - \"'workers' must be positive\"".to_string());
        }
        w
    } else {
        num_cpus()
    };

    // Parse charset
    let charset = build_charset(charset_str.as_deref(), charset_file.as_deref())?;

    let min_password_len = min_password_len.unwrap_or(1);
    let max_password_len = max_password_len.unwrap_or(10);
    let file_number = file_number.unwrap_or(0);

    // Validate starting_password
    let starting_password = if let Some(sp) = starting_password {
        let sp_bytes = sp.as_bytes().to_vec();
        let len = sp_bytes.len();

        // Check length constraints
        if password_dictionary.is_none() {
            if len < min_password_len || len > max_password_len {
                return Err("CLI argument error - \"'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration\"".to_string());
            }

            // Check that all chars are in charset
            for &b in &sp_bytes {
                if !charset.contains(&b) {
                    return Err("CLI argument error - \"'startingPassword' uses characters out of the generation charset\"".to_string());
                }
            }
        }

        Some(sp_bytes)
    } else {
        None
    };

    Ok(Args {
        input_file,
        workers,
        password_dictionary,
        charset,
        charset_file,
        min_password_len,
        max_password_len,
        file_number,
        starting_password,
    })
}

fn get_arg_value(args: &[String], i: usize, name: &str) -> Result<String, String> {
    if i >= args.len() {
        Err(format!("error: missing value for argument '{}'", name))
    } else {
        Ok(args[i].clone())
    }
}

fn parse_usize(s: &str, name: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|_| format!("error: invalid value for '{}': {}", name, s))
}

fn build_charset(charset_str: Option<&str>, charset_file: Option<&str>) -> Result<Vec<u8>, String> {
    let mut charset = Vec::new();

    if let Some(cf) = charset_file {
        // Read charset file
        let content = std::fs::read(cf).map_err(|e| {
            format!("CLI argument error - \"'charsetFile' error: {}\"", e)
        })?;
        for &b in &content {
            if b != b'\n' && b != b'\r' && !charset.contains(&b) {
                charset.push(b);
            }
        }
        return Ok(charset);
    }

    let cs = charset_str.unwrap_or("lud");

    for c in cs.chars() {
        match c {
            'l' => {
                for b in b'a'..=b'z' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            'u' => {
                for b in b'A'..=b'Z' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            'd' => {
                for b in b'0'..=b'9' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            'h' => {
                for b in b'0'..=b'9' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
                for b in b'a'..=b'f' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            'H' => {
                for b in b'0'..=b'9' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
                for b in b'A'..=b'F' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            's' => {
                let symbols: &[u8] = b" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
                for &b in symbols {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            _ => {
                return Err(format!("CLI argument error - \"Unknown charset option '{}'\"", c));
            }
        }
    }

    Ok(charset)
}

fn num_cpus() -> usize {
    // Read /proc/cpuinfo to get number of CPUs
    if let Ok(content) = std::fs::read_to_string("/proc/cpuinfo") {
        let count = content.lines()
            .filter(|l| l.starts_with("processor"))
            .count();
        if count > 0 {
            return count;
        }
    }
    1
}

fn print_help(prog: &str) {
    println!("Find the password of protected ZIP files");
    println!();
    println!("Usage: {} [OPTIONS] --inputFile <inputFile>", prog);
    println!();
    println!("Options:");
    println!("  -i, --inputFile <inputFile>                    path to zip input file");
    println!("  -w, --workers <workers>                        number of workers");
    println!("  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file");
    println!("  -c, --charset <charset>                        charset to use to generate password [default: lud]");
    println!("      --charsetFile <charsetFile>                path to a charset file");
    println!("      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]");
    println!("      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]");
    println!("      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]");
    println!("  -s, --startingPassword <startingPassword>      password to start from");
    println!("  -h, --help                                     Print help");
