                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
            }
            'h' => {
                for b in b'0'..=b'9' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
                for b in b'a'..=b'f' {
                    if !charset.contains(&b) {
                        charset.push(b);
                    }
                }
