    },
}

#[derive(Debug, Clone)]
pub struct ZipEntryInfo {
    pub name: String,
    pub encryption: EncryptionType,
    pub encrypted_data: Vec<u8>,
}

#[derive(Debug)]
pub struct ZipError(pub String);

impl fmt::Display for ZipError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    if offset + 2 > data.len() { return 0; }
    u16::from_le_bytes([data[offset], data[offset+1]])
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    if offset + 4 > data.len() { return 0; }
    u32::from_le_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]])
}

// Parse an AES extra field (tag 0x9901)
fn parse_aes_extra(extra: &[u8]) -> Option<(u8, u16)> {
    let mut pos = 0;
    while pos + 4 <= extra.len() {
        let tag = read_u16_le(extra, pos);
        let size = read_u16_le(extra, pos + 2) as usize;
        pos += 4;

        if tag == 0x9901 {
            // AES extra data
            if size < 7 || pos + size > extra.len() {
                return None;
            }
            // version = 2 bytes
            // vendor = 2 bytes
            // aes_strength = 1 byte (1=128, 2=192, 3=256)
            // compression = 2 bytes
            let aes_strength = extra[pos + 4];
            let compression = read_u16_le(extra, pos + 5);
            return Some((aes_strength, compression));
        }

        pos += size;
    }
    None
}

