// ZipCrypto (traditional ZIP encryption) implementation

static CRC_TABLE: std::sync::OnceLock<[u32; 256]> = std::sync::OnceLock::new();

fn get_crc_table() -> &'static [u32; 256] {
    CRC_TABLE.get_or_init(|| {
        let mut table = [0u32; 256];
        for i in 0..256 {
            let mut c = i as u32;
            for _ in 0..8 {
                if c & 1 != 0 {
                    c = 0xEDB88320u32 ^ (c >> 1);
                } else {
                    c >>= 1;
                }
            }
            table[i] = c;
        }
        table
    })
}

#[inline]
fn crc32_byte(crc: u32, byte: u8) -> u32 {
    let table = get_crc_table();
    table[((crc ^ byte as u32) & 0xff) as usize] ^ (crc >> 8)
}

#[inline]
fn update_keys(keys: &mut [u32; 3], byte: u8) {
    keys[0] = crc32_byte(keys[0], byte);
    keys[1] = keys[1].wrapping_add(keys[0] & 0xff);
    keys[1] = keys[1].wrapping_mul(134775813).wrapping_add(1);
    keys[2] = crc32_byte(keys[2], (keys[1] >> 24) as u8);
}

#[inline]
fn decrypt_byte(keys: &[u32; 3]) -> u8 {
    let tmp = (keys[2] | 2) as u16;
    (((tmp as u32) * ((tmp ^ 1) as u32)) >> 8) as u8
}

fn init_keys(password: &[u8]) -> [u32; 3] {
    let mut keys = [0x12345678u32, 0x23456789u32, 0x34567890u32];
    for &b in password {
        update_keys(&mut keys, b);
    }
    keys
}

pub fn check_password(password: &[u8], header: &[u8], crc32: u32, mod_time_byte: u8, use_mod_time: bool) -> bool {
    if header.len() < 12 {
        return false;
    }

    let mut keys = init_keys(password);

    // Decrypt the 12-byte header
    let mut last_byte = 0u8;
    for i in 0..12 {
        let k = decrypt_byte(&keys);
        let decrypted = k ^ header[i];
        update_keys(&mut keys, decrypted);
        if i == 11 {
            last_byte = decrypted;
        }
    }

    // Check: last byte of decrypted header should match high byte of CRC32
    // Or if data descriptor flag is set, it should match high byte of mod_time
    let expected = if use_mod_time {
        mod_time_byte
    } else {
        ((crc32 >> 24) & 0xff) as u8
    };

    last_byte == expected
}
