// Password generator for brute force attack

pub struct PasswordGenerator {
    charset: Vec<u8>,
    min_len: usize,
    max_len: usize,
    current: Vec<usize>,  // indices into charset
    done: bool,
}

impl PasswordGenerator {
    pub fn new(
        charset: Vec<u8>,
        min_len: usize,
        max_len: usize,
        start_len: usize,
        start_indices: Vec<usize>,
    ) -> Self {
        if charset.is_empty() || max_len < min_len {
            return PasswordGenerator {
                charset,
                min_len,
                max_len,
                current: vec![],
                done: true,
            };
        }

        PasswordGenerator {
            charset,
            min_len,
            max_len,
            current: start_indices,
            done: false,
        }
    }

    pub fn next(&mut self) -> Option<Vec<u8>> {
        if self.done {
            return None;
        }

        let charset_len = self.charset.len();

        // Get current password
        let password: Vec<u8> = self.current.iter()
            .map(|&i| self.charset[i])
            .collect();

        // Increment
        self.increment();

        Some(password)
    }

    fn increment(&mut self) {
        let charset_len = self.charset.len();
        let cur_len = self.current.len();

        // Increment from the rightmost position
        let mut pos = cur_len;
        loop {
            if pos == 0 {
                // Need to increase length
                let new_len = cur_len + 1;
                if new_len > self.max_len {
                    self.done = true;
                    return;
                }
                self.current = vec![0; new_len];
                return;
            }
            pos -= 1;
            self.current[pos] += 1;
            if self.current[pos] < charset_len {
                return;
            }
            self.current[pos] = 0;
        }
    }
}
