use std::fmt;

#[derive(Debug, Clone)]
pub enum EncryptionType {
    ZipCrypto {
        crc32: u32,
        mod_time_byte: u8,
        use_mod_time: bool,
        compress_method: u16,
        uncompressed_size: u32,
    },
    AesWinzip {
        aes_strength: u8,
        salt: Vec<u8>,
        pwd_verifier: [u8; 2],
    },
}

#[derive(Debug, Clone)]
pub struct ZipEntryInfo {
    pub name: String,
    pub file_number: usize,
    pub encryption: EncryptionType,
    pub encrypted_data: Vec<u8>,
}

#[derive(Debug)]
pub struct ZipError(pub String);

impl fmt::Display for ZipError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    if offset + 2 > data.len() { return 0; }
    u16::from_le_bytes([data[offset], data[offset+1]])
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    if offset + 4 > data.len() { return 0; }
    u32::from_le_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]])
}

fn parse_aes_extra(extra: &[u8]) -> Option<(u8, u16)> {
    let mut pos = 0;
    while pos + 4 <= extra.len() {
        let tag = read_u16_le(extra, pos);
        let size = read_u16_le(extra, pos + 2) as usize;
        pos += 4;

        if tag == 0x9901 {
            if size < 7 || pos + size > extra.len() {
                return None;
            }
            let aes_strength = extra[pos + 4];
            let compression = read_u16_le(extra, pos + 5);
            return Some((aes_strength, compression));
        }

        pos += size;
    }
    None
}

pub fn parse_zip(data: &[u8], file_number: usize) -> Result<ZipEntryInfo, ZipError> {
    let eocd_pos = find_eocd(data)?;

    let cd_entries = read_u16_le(data, eocd_pos + 10) as usize;
    let cd_offset = read_u32_le(data, eocd_pos + 16) as usize;

    if cd_offset >= data.len() {
        return Err(ZipError("invalid central directory offset".to_string()));
    }

    let mut cd_pos = cd_offset;
    let mut entry_idx = 0;
    let mut total_entries = 0;

    // Count entries and find the target
    loop {
        if cd_pos + 4 > data.len() {
            break;
        }

        let sig = read_u32_le(data, cd_pos);
        if sig != 0x02014b50 {
            break;
        }

        let fname_len = read_u16_le(data, cd_pos + 28) as usize;
        let extra_len = read_u16_le(data, cd_pos + 30) as usize;
        let comment_len = read_u16_le(data, cd_pos + 32) as usize;
        let local_offset = read_u32_le(data, cd_pos + 42) as usize;
        let cd_flags = read_u16_le(data, cd_pos + 8);

        let name_start = cd_pos + 46;
        let name = if name_start + fname_len <= data.len() {
            String::from_utf8_lossy(&data[name_start..name_start+fname_len]).to_string()
        } else {
            String::new()
        };

        if entry_idx == file_number {
            // This is our target entry
            let is_encrypted = (cd_flags & 1) != 0;

            if !is_encrypted {
                return Err(ZipError(format!(
                    "the selected file in the archive is not encrypted (file_number:{} file_name:{})",
                    file_number, name
                )));
            }

            return parse_local_entry(data, local_offset, &name, file_number);
        }

        cd_pos += 46 + fname_len + extra_len + comment_len;
        entry_idx += 1;
        total_entries += 1;
    }

    Err(ZipError(format!(
        "file number {} is out of range (archive has {} entries)",
        file_number, total_entries
    )))
}

fn find_eocd(data: &[u8]) -> Result<usize, ZipError> {
    if data.len() < 22 {
        return Err(ZipError("invalid Zip archive: Could not find EOCD".to_string()));
    }

    let search_start = if data.len() > 65535 + 22 { data.len() - 65535 - 22 } else { 0 };

    let mut pos = data.len() - 4;

    loop {
        if read_u32_le(data, pos) == 0x06054b50 {
            return Ok(pos);
        }
        if pos == 0 || pos <= search_start {
            break;
        }
        pos -= 1;
    }

    Err(ZipError("invalid Zip archive: Could not find EOCD".to_string()))
}

fn parse_local_entry(data: &[u8], offset: usize, name: &str, file_number: usize) -> Result<ZipEntryInfo, ZipError> {
    if offset + 30 > data.len() {
        return Err(ZipError("truncated local file header".to_string()));
    }

    let sig = read_u32_le(data, offset);
    if sig != 0x04034b50 {
        return Err(ZipError("invalid local file header signature".to_string()));
    }

    let flags = read_u16_le(data, offset + 6);
    let compress_method = read_u16_le(data, offset + 8);
    let mod_time = read_u16_le(data, offset + 10);
    let crc32 = read_u32_le(data, offset + 14);
    let comp_size = read_u32_le(data, offset + 18) as usize;
    let uncomp_size = read_u32_le(data, offset + 22) as usize;
    let fname_len = read_u16_le(data, offset + 26) as usize;
    let extra_len = read_u16_le(data, offset + 28) as usize;

    let data_offset = offset + 30 + fname_len + extra_len;

    let is_encrypted = (flags & 1) != 0;

    if !is_encrypted {
        return Err(ZipError(format!(
            "the selected file in the archive is not encrypted (file_number:{} file_name:{})",
            file_number, name
        )));
    }

    // Parse extra field for AES
    let extra_start = offset + 30 + fname_len;
    let extra = &data[extra_start..extra_start + extra_len];

    // Check if it's AES encrypted (compress_method == 99)
    if compress_method == 99 {
        if let Some((aes_strength, _actual_compress)) = parse_aes_extra(extra) {
            let salt_len = match aes_strength {
                1 => 8,
                2 => 12,
                3 => 16,
                _ => return Err(ZipError(format!("unknown AES strength: {}", aes_strength))),
            };

            if data_offset + salt_len + 2 > data.len() {
                return Err(ZipError("truncated AES encrypted data".to_string()));
            }

            let salt = data[data_offset..data_offset + salt_len].to_vec();
            let pwd_verifier = [
                data[data_offset + salt_len],
                data[data_offset + salt_len + 1],
            ];

            let end_pos = (data_offset + comp_size).min(data.len());
            let encrypted_data = data[data_offset..end_pos].to_vec();

            return Ok(ZipEntryInfo {
                name: name.to_string(),
                file_number,
                encryption: EncryptionType::AesWinzip {
                    aes_strength,
                    salt,
                    pwd_verifier,
                },
                encrypted_data,
            });
        }
        return Err(ZipError("AES encrypted file without AES extra field".to_string()));
    }

    // ZipCrypto
    let use_data_descriptor = (flags & 8) != 0;
    let use_mod_time = use_data_descriptor;
    let mod_time_byte = ((mod_time >> 8) & 0xff) as u8;

    if data_offset + 12 > data.len() {
        return Err(ZipError("truncated ZipCrypto header".to_string()));
    }

    let end_pos = (data_offset + comp_size).min(data.len());
    let encrypted_data = data[data_offset..end_pos].to_vec();

    Ok(ZipEntryInfo {
        name: name.to_string(),
        file_number,
        encryption: EncryptionType::ZipCrypto {
            crc32,
            mod_time_byte,
            use_mod_time,
            compress_method,
            uncompressed_size: uncomp_size as u32,
        },
        encrypted_data,
    })
}
