// ZipCrypto (traditional ZIP encryption) implementation

static CRC_TABLE: std::sync::OnceLock<[u32; 256]> = std::sync::OnceLock::new();

fn get_crc_table() -> &'static [u32; 256] {
    CRC_TABLE.get_or_init(|| {
        let mut table = [0u32; 256];
        for i in 0..256u32 {
            let mut c = i;
            for _ in 0..8 {
                if c & 1 != 0 {
                    c = 0xEDB88320u32 ^ (c >> 1);
                } else {
                    c >>= 1;
                }
            }
            table[i as usize] = c;
        }
        table
    })
}

#[inline]
pub fn crc32_byte(crc: u32, byte: u8) -> u32 {
    let table = get_crc_table();
    table[((crc ^ byte as u32) & 0xff) as usize] ^ (crc >> 8)
}

#[inline]
pub fn update_keys(keys: &mut [u32; 3], byte: u8) {
    keys[0] = crc32_byte(keys[0], byte);
    keys[1] = keys[1].wrapping_add(keys[0] & 0xff);
    keys[1] = keys[1].wrapping_mul(134775813).wrapping_add(1);
    keys[2] = crc32_byte(keys[2], (keys[1] >> 24) as u8);
}

#[inline]
pub fn decrypt_byte(keys: &[u32; 3]) -> u8 {
    let tmp = (keys[2] | 2) as u16;
    (((tmp as u32) * ((tmp ^ 1) as u32)) >> 8) as u8
}

pub fn init_keys(password: &[u8]) -> [u32; 3] {
    let mut keys = [0x12345678u32, 0x23456789u32, 0x34567890u32];
    for &b in password {
        update_keys(&mut keys, b);
    }
    keys
}

pub fn compute_crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    for &b in data {
        crc = crc32_byte(crc, b);
    }
    crc ^ 0xffffffff
}

pub fn check_password(
    password: &[u8],
    encrypted_data: &[u8],
    crc32: u32,
    mod_time_byte: u8,
    use_mod_time: bool,
    compress_method: u16,
) -> bool {
    if encrypted_data.len() < 12 {
        return false;
    }

    let mut keys = init_keys(password);

    // Decrypt the 12-byte header
    let mut last_byte = 0u8;
    for i in 0..12 {
        let k = decrypt_byte(&keys);
        let decrypted = k ^ encrypted_data[i];
        update_keys(&mut keys, decrypted);
        if i == 11 {
            last_byte = decrypted;
        }
    }

    // Quick check: last byte of decrypted header
    let expected = if use_mod_time {
        mod_time_byte
    } else {
        ((crc32 >> 24) & 0xff) as u8
    };

    if last_byte != expected {
        return false;
    }

    // Full verification: decrypt remaining data and check CRC32
    // Only for STORED files (compress_method == 0)
    // For DEFLATE, we'd need to decompress first
    if compress_method == 0 {
        let data_bytes = &encrypted_data[12..];
        let mut decrypted = vec![0u8; data_bytes.len()];

        for (i, &b) in data_bytes.iter().enumerate() {
            let k = decrypt_byte(&keys);
            decrypted[i] = k ^ b;
            update_keys(&mut keys, decrypted[i]);
        }

        let computed_crc = compute_crc32(&decrypted);
        return computed_crc == crc32;
    }

    // For DEFLATE compressed data, we do full decryption and decompression
    if compress_method == 8 {
        let data_bytes = &encrypted_data[12..];
        let mut decrypted = vec![0u8; data_bytes.len()];

        for (i, &b) in data_bytes.iter().enumerate() {
            let k = decrypt_byte(&keys);
            decrypted[i] = k ^ b;
            update_keys(&mut keys, decrypted[i]);
        }

        // Try to inflate the decrypted data
        if let Some(decompressed) = inflate_raw(&decrypted) {
            let computed_crc = compute_crc32(&decompressed);
            return computed_crc == crc32;
        }

        // If decompression fails, this wasn't the right password
        return false;
    }

    // For other compression methods, rely on the header check only
    true
}

// Simple DEFLATE raw inflate implementation
// Returns None if decompression fails (wrong password or bad data)
fn inflate_raw(data: &[u8]) -> Option<Vec<u8>> {
    let mut output = Vec::new();
    let mut bit_reader = BitReader::new(data);

    loop {
        let bfinal = bit_reader.read_bits(1)?;
        let btype = bit_reader.read_bits(2)?;

        match btype {
            0 => {
                // No compression (stored)
                bit_reader.align_to_byte();
                let len = bit_reader.read_u16_le()? as usize;
                let nlen = bit_reader.read_u16_le()? as usize;
                if (len ^ nlen) != 0xffff {
                    return None; // Corruption
                }
                for _ in 0..len {
                    output.push(bit_reader.read_byte()?);
                }
            }
            1 => {
                // Fixed Huffman codes
                if !inflate_fixed_huffman(&mut bit_reader, &mut output) {
                    return None;
                }
            }
            2 => {
                // Dynamic Huffman codes
                if !inflate_dynamic_huffman(&mut bit_reader, &mut output) {
                    return None;
                }
            }
            _ => return None, // Reserved
        }

        if bfinal == 1 {
            break;
        }
    }

    Some(output)
}

struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,
    bit_buf: u32,
    bits_in_buf: u8,
}

impl<'a> BitReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        BitReader { data, pos: 0, bit_buf: 0, bits_in_buf: 0 }
    }

    fn fill_buf(&mut self) {
        while self.bits_in_buf <= 24 && self.pos < self.data.len() {
            self.bit_buf |= (self.data[self.pos] as u32) << self.bits_in_buf;
            self.bits_in_buf += 8;
            self.pos += 1;
        }
    }

    fn read_bits(&mut self, n: u8) -> Option<u32> {
        self.fill_buf();
        if self.bits_in_buf < n {
            return None;
        }
        let val = self.bit_buf & ((1u32 << n) - 1);
        self.bit_buf >>= n;
        self.bits_in_buf -= n;
        Some(val)
    }

    fn align_to_byte(&mut self) {
        let rem = self.bits_in_buf % 8;
        if rem > 0 {
            self.bit_buf >>= rem;
            self.bits_in_buf -= rem;
        }
    }

    fn read_u16_le(&mut self) -> Option<u16> {
        // Read from byte-aligned stream
        self.fill_buf();
        if self.bits_in_buf < 16 {
            return None;
        }
        let val = (self.bit_buf & 0xffff) as u16;
        self.bit_buf >>= 16;
        self.bits_in_buf -= 16;
        Some(val)
    }

    fn read_byte(&mut self) -> Option<u8> {
        self.fill_buf();
        if self.bits_in_buf < 8 {
            return None;
        }
        let val = (self.bit_buf & 0xff) as u8;
        self.bit_buf >>= 8;
        self.bits_in_buf -= 8;
        Some(val)
    }

    fn read_bits_rev(&mut self, n: u8) -> Option<u32> {
        // Read n bits and reverse them (for Huffman code matching)
        let val = self.read_bits(n)?;
        let mut rev = 0u32;
        let mut v = val;
        for _ in 0..n {
            rev = (rev << 1) | (v & 1);
            v >>= 1;
        }
        Some(rev)
    }
}

// Fixed Huffman codes as per RFC 1951
fn get_fixed_lit_len_table() -> Vec<(u8, u16)> {
    // Returns (bit_len, code) for each symbol 0..=287
    let mut table = vec![(0u8, 0u16); 288];

    // 0-143: 8 bits, starting at 00110000
    for i in 0u16..=143 {
        table[i as usize] = (8, 0b00110000 + i);
    }
    // 144-255: 9 bits, starting at 110010000
    for i in 144u16..=255 {
        table[i as usize] = (9, 0b110010000 + (i - 144));
    }
    // 256-279: 7 bits, starting at 0000000
    for i in 256u16..=279 {
        table[i as usize] = (7, i - 256);
    }
    // 280-287: 8 bits, starting at 11000000
    for i in 280u16..=287 {
        table[i as usize] = (8, 0b11000000 + (i - 280));
    }

    table
}

// Build a lookup table from Huffman codes
// Returns a hashmap of (reversed_code -> symbol) pairs
fn build_huffman_decode_table(lengths: &[u8]) -> Option<std::collections::HashMap<(u8, u16), u16>> {
    let max_bits = *lengths.iter().max()? as u8;
    if max_bits == 0 {
        return Some(std::collections::HashMap::new());
    }

    // Count codes per length
    let mut count = vec![0usize; max_bits as usize + 1];
    for &l in lengths {
        if l > 0 {
            count[l as usize] += 1;
        }
    }

    // Find starting codes
    let mut next_code = vec![0u32; max_bits as usize + 2];
    let mut code = 0u32;
    for bits in 1..=(max_bits as usize) {
        code = (code + count[bits-1] as u32) << 1;
        next_code[bits] = code;
    }

    let mut table = std::collections::HashMap::new();

    for (sym, &len) in lengths.iter().enumerate() {
        if len > 0 {
            let c = next_code[len as usize];
            // Reverse the bits for LSB-first reading
            let rev_code = reverse_bits(c, len) as u16;
            table.insert((len, rev_code), sym as u16);
            next_code[len as usize] += 1;
        }
    }

    Some(table)
}

fn reverse_bits(val: u32, n: u8) -> u32 {
    let mut rev = 0u32;
    let mut v = val;
    for _ in 0..n {
        rev = (rev << 1) | (v & 1);
        v >>= 1;
    }
    rev
}

fn decode_huffman(reader: &mut BitReader, table: &std::collections::HashMap<(u8, u16), u16>, max_bits: u8) -> Option<u16> {
    let mut code = 0u16;
    for bits in 1..=max_bits {
        let bit = reader.read_bits(1)? as u16;
        code |= bit << (bits - 1);
        if let Some(&sym) = table.get(&(bits, code)) {
            return Some(sym);
        }
    }
    None
}

