struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,
    bit_buf: u32,
    bits_in_buf: u8,
}

impl<'a> BitReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        BitReader { data, pos: 0, bit_buf: 0, bits_in_buf: 0 }
    }

    fn fill_buf(&mut self) {
        while self.bits_in_buf <= 24 && self.pos < self.data.len() {
            self.bit_buf |= (self.data[self.pos] as u32) << self.bits_in_buf;
            self.bits_in_buf += 8;
            self.pos += 1;
        }
    }

    fn read_bits(&mut self, n: u8) -> Option<u32> {
        self.fill_buf();
        if self.bits_in_buf < n {
            return None;
        }
        let val = self.bit_buf & ((1u32 << n) - 1);
        self.bit_buf >>= n;
        self.bits_in_buf -= n;
        Some(val)
    }

    fn align_to_byte(&mut self) {
        let rem = self.bits_in_buf % 8;
        if rem > 0 {
            self.bit_buf >>= rem;
            self.bits_in_buf -= rem;
        }
    }

    fn read_u16_le(&mut self) -> Option<u16> {
        // Read from byte-aligned stream
        self.fill_buf();
        if self.bits_in_buf < 16 {
            return None;
        }
        let val = (self.bit_buf & 0xffff) as u16;
        self.bit_buf >>= 16;
        self.bits_in_buf -= 16;
        Some(val)
    }

    fn read_byte(&mut self) -> Option<u8> {
        self.fill_buf();
        if self.bits_in_buf < 8 {
            return None;
        }
        let val = (self.bit_buf & 0xff) as u8;
        self.bit_buf >>= 8;
        self.bits_in_buf -= 8;
        Some(val)
    }

    fn read_bits_rev(&mut self, n: u8) -> Option<u32> {
        // Read n bits and reverse them (for Huffman code matching)
        let val = self.read_bits(n)?;
        let mut rev = 0u32;
        let mut v = val;
        for _ in 0..n {
            rev = (rev << 1) | (v & 1);
            v >>= 1;
        }
        Some(rev)
    }
}

// Fixed Huffman codes as per RFC 1951
fn get_fixed_lit_len_table() -> Vec<(u8, u16)> {
    // Returns (bit_len, code) for each symbol 0..=287
    let mut table = vec![(0u8, 0u16); 288];

    // 0-143: 8 bits, starting at 00110000
    for i in 0u16..=143 {
        table[i as usize] = (8, 0b00110000 + i);
    }
    // 144-255: 9 bits, starting at 110010000
    for i in 144u16..=255 {
        table[i as usize] = (9, 0b110010000 + (i - 144));
    }
    // 256-279: 7 bits, starting at 0000000
    for i in 256u16..=279 {
        table[i as usize] = (7, i - 256);
    }
    // 280-287: 8 bits, starting at 11000000
    for i in 280u16..=287 {
        table[i as usize] = (8, 0b11000000 + (i - 280));
    }

    table
}

// Build a lookup table from Huffman codes
// Returns a hashmap of (reversed_code -> symbol) pairs
fn build_huffman_decode_table(lengths: &[u8]) -> Option<std::collections::HashMap<(u8, u16), u16>> {
    let max_bits = *lengths.iter().max()? as u8;
    if max_bits == 0 {
        return Some(std::collections::HashMap::new());
    }

    // Count codes per length
    let mut count = vec![0usize; max_bits as usize + 1];
    for &l in lengths {
        if l > 0 {
            count[l as usize] += 1;
        }
    }

    // Find starting codes
    let mut next_code = vec![0u32; max_bits as usize + 2];
    let mut code = 0u32;
    for bits in 1..=(max_bits as usize) {
        code = (code + count[bits-1] as u32) << 1;
        next_code[bits] = code;
    }

    let mut table = std::collections::HashMap::new();

    for (sym, &len) in lengths.iter().enumerate() {
        if len > 0 {
            let c = next_code[len as usize];
            // Reverse the bits for LSB-first reading
            let rev_code = reverse_bits(c, len) as u16;
            table.insert((len, rev_code), sym as u16);
            next_code[len as usize] += 1;
        }
    }

    Some(table)
}

fn reverse_bits(val: u32, n: u8) -> u32 {
    let mut rev = 0u32;
    let mut v = val;
    for _ in 0..n {
        rev = (rev << 1) | (v & 1);
        v >>= 1;
    }
    rev
}

fn decode_huffman(reader: &mut BitReader, table: &std::collections::HashMap<(u8, u16), u16>, max_bits: u8) -> Option<u16> {
    let mut code = 0u16;
    for bits in 1..=max_bits {
        let bit = reader.read_bits(1)? as u16;
        code |= bit << (bits - 1);
        if let Some(&sym) = table.get(&(bits, code)) {
            return Some(sym);
        }
    }
    None
}

// Length and distance tables from RFC 1951
static LENGTH_BASE: [u16; 29] = [
