];

fn inflate_fixed_huffman(reader: &mut BitReader, output: &mut Vec<u8>) -> bool {
    // Build fixed huffman tables
    let mut lit_lengths = vec![0u8; 288];
    for i in 0..144 { lit_lengths[i] = 8; }
    for i in 144..256 { lit_lengths[i] = 9; }
    for i in 256..280 { lit_lengths[i] = 7; }
    for i in 280..288 { lit_lengths[i] = 8; }

    let lit_table = match build_huffman_decode_table(&lit_lengths) {
        Some(t) => t,
        None => return false,
    };

    let dist_lengths = vec![5u8; 32];
    let dist_table = match build_huffman_decode_table(&dist_lengths) {
        Some(t) => t,
        None => return false,
    };

    inflate_block(reader, output, &lit_table, 9, &dist_table, 5)
}

fn inflate_dynamic_huffman(reader: &mut BitReader, output: &mut Vec<u8>) -> bool {
    let hlit = match reader.read_bits(5) {
        Some(v) => v as usize + 257,
        None => return false,
    };
    let hdist = match reader.read_bits(5) {
        Some(v) => v as usize + 1,
        None => return false,
    };
    let hclen = match reader.read_bits(4) {
        Some(v) => v as usize + 4,
        None => return false,
    };

    // Read code length code lengths (in order)
    static CL_ORDER: [usize; 19] = [16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15];
    let mut cl_lengths = vec![0u8; 19];
    for i in 0..hclen {
        cl_lengths[CL_ORDER[i]] = match reader.read_bits(3) {
            Some(v) => v as u8,
            None => return false,
        };
    }

    let cl_table = match build_huffman_decode_table(&cl_lengths) {
        Some(t) => t,
        None => return false,
    };
    let cl_max = *cl_lengths.iter().max().unwrap_or(&0);

    // Read the actual code lengths
    let total = hlit + hdist;
    let mut lengths = vec![0u8; total];
    let mut i = 0;
    while i < total {
        let sym = match decode_huffman(reader, &cl_table, cl_max) {
            Some(s) => s,
            None => return false,
        };

        match sym {
            0..=15 => {
                lengths[i] = sym as u8;
                i += 1;
            }
            16 => {
                if i == 0 { return false; }
                let extra = match reader.read_bits(2) {
                    Some(v) => v as usize + 3,
                    None => return false,
                };
                let prev = lengths[i-1];
                for _ in 0..extra {
                    if i >= total { return false; }
                    lengths[i] = prev;
                    i += 1;
                }
            }
            17 => {
                let extra = match reader.read_bits(3) {
                    Some(v) => v as usize + 3,
                    None => return false,
                };
                for _ in 0..extra {
                    if i >= total { return false; }
                    lengths[i] = 0;
                    i += 1;
                }
            }
            18 => {
                let extra = match reader.read_bits(7) {
                    Some(v) => v as usize + 11,
                    None => return false,
                };
                for _ in 0..extra {
                    if i >= total { return false; }
                    lengths[i] = 0;
                    i += 1;
                }
            }
            _ => return false,
        }
    }

    let lit_lengths = &lengths[..hlit];
    let dist_lengths = &lengths[hlit..];

    let lit_table = match build_huffman_decode_table(lit_lengths) {
        Some(t) => t,
        None => return false,
    };
    let dist_table = match build_huffman_decode_table(dist_lengths) {
        Some(t) => t,
        None => return false,
    };

    let lit_max = *lit_lengths.iter().max().unwrap_or(&0);
    let dist_max = *dist_lengths.iter().max().unwrap_or(&0);

    inflate_block(reader, output, &lit_table, lit_max, &dist_table, dist_max)
}

fn inflate_block(
    reader: &mut BitReader,
    output: &mut Vec<u8>,
    lit_table: &std::collections::HashMap<(u8, u16), u16>,
    lit_max: u8,
    dist_table: &std::collections::HashMap<(u8, u16), u16>,
    dist_max: u8,
) -> bool {
    loop {
        let sym = match decode_huffman(reader, lit_table, lit_max) {
            Some(s) => s,
            None => return false,
        };

        if sym == 256 {
            break; // End of block
        } else if sym < 256 {
            output.push(sym as u8);
        } else {
            // Length-distance pair
            let len_idx = (sym - 257) as usize;
            if len_idx >= 29 { return false; }

            let extra_bits = LENGTH_EXTRA[len_idx];
            let extra = if extra_bits > 0 {
                match reader.read_bits(extra_bits) {
                    Some(v) => v as u16,
                    None => return false,
                }
            } else {
                0
            };
            let length = LENGTH_BASE[len_idx] + extra;

            // Read distance
            let dist_sym = match decode_huffman(reader, dist_table, dist_max) {
                Some(s) => s,
                None => return false,
            } as usize;

            if dist_sym >= 30 { return false; }
            let dist_extra_bits = DIST_EXTRA[dist_sym];
            let dist_extra = if dist_extra_bits > 0 {
                match reader.read_bits(dist_extra_bits) {
                    Some(v) => v as u16,
                    None => return false,
                }
            } else {
                0
            };
            let distance = DIST_BASE[dist_sym] + dist_extra;

            let out_len = output.len();
            if distance as usize > out_len { return false; }

            let start = out_len - distance as usize;
            for i in 0..length as usize {
                let byte = output[start + (i % distance as usize)];
                output.push(byte);
            }
        }
    }

    true
}
