    fn read_bits_rev(&mut self, n: u8) -> Option<u32> {
        // Read n bits and reverse them (for Huffman code matching)
        let val = self.read_bits(n)?;
        let mut rev = 0u32;
        let mut v = val;
        for _ in 0..n {
            rev = (rev << 1) | (v & 1);
            v >>= 1;
        }
        Some(rev)
    }
