            std::process::exit(1);
        }
    };

    let reader = io::BufReader::new(file);
    let passwords: Vec<String> = reader.lines()
        .filter_map(|l| l.ok())
        .collect();

    if passwords.is_empty() {
        return None;
    }

    let found = Arc::new(Mutex::new(None::<String>));
    let stop = Arc::new(AtomicBool::new(false));

    let actual_workers = num_workers.min(passwords.len());
    let chunk_size = (passwords.len() + actual_workers - 1) / actual_workers;

    let mut handles = Vec::new();

    for chunk in passwords.chunks(chunk_size) {
        let chunk = chunk.to_vec();
        let entry = entry.clone();
        let found = found.clone();
        let stop = stop.clone();

        let handle = thread::spawn(move || {
            for password in chunk {
                if stop.load(Ordering::Relaxed) {
                    break;
                }
                if check_password(&entry, password.as_bytes()) {
                    let mut f = found.lock().unwrap();
                    if f.is_none() {
                        *f = Some(password);
                    }
                    stop.store(true, Ordering::Relaxed);
                    break;
                }
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let result = found.lock().unwrap().take();
    result
}

