fn main() {
    // Test PBKDF2-HMAC-SHA1 implementation
    // Expected: password 'ab', salt a35877e3ac0651f9, verifier c718
    let password = b"ab";
    let salt = hex_decode("a35877e3ac0651f9");
    let expected_verifier = hex_decode("c718");

    let dk = pbkdf2_hmac_sha1(password, &salt, 1000, 34); // 16 + 16 + 2 = 34
    let derived_verifier = &dk[32..34];

    println!("Derived verifier: {}", hex_encode(derived_verifier));
    println!("Expected verifier: {}", hex_encode(&expected_verifier));
    println!("Match: {}", derived_verifier == expected_verifier.as_slice());
}

fn hex_decode(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i+2], 16).unwrap())
        .collect()
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

fn sha1_hash(data: &[u8]) -> [u8; 20] {
    let mut h = [0x67452301u32, 0xEFCDAB89u32, 0x98BADCFEu32, 0x10325476u32, 0xC3D2E1F0u32];

    let mut msg = data.to_vec();
    let bit_len = (data.len() as u64) * 8;

    msg.push(0x80);
    while (msg.len() % 64) != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }

        let [mut a, mut b, mut c, mut d, mut e] = [h[0], h[1], h[2], h[3], h[4]];

        for i in 0..80 {
            let (f, k) = match i {
                0..=19  => ((b & c) | ((!b) & d), 0x5A827999u32),
                20..=39 => (b ^ c ^ d,             0x6ED9EBA1u32),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32),
                _       => (b ^ c ^ d,             0xCA62C1D6u32),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }

    let mut result = [0u8; 20];
    for i in 0..5 {
        result[i*4..(i+1)*4].copy_from_slice(&h[i].to_be_bytes());
    }
    result
}

fn sha1_hmac(key: &[u8], data: &[u8]) -> [u8; 20] {
    let mut k = if key.len() > 64 {
        sha1_hash(key).to_vec()
    } else {
        key.to_vec()
    };
    k.resize(64, 0);

    let ipad: Vec<u8> = k.iter().map(|&b| b ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|&b| b ^ 0x5C).collect();

    let mut inner = ipad;
    inner.extend_from_slice(data);
    let inner_hash = sha1_hash(&inner);

    let mut outer = opad;
    outer.extend_from_slice(&inner_hash);
    sha1_hash(&outer)
}

fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iterations: u32, dk_len: usize) -> Vec<u8> {
    let hash_len = 20;
    let num_blocks = (dk_len + hash_len - 1) / hash_len;

    let mut dk = Vec::with_capacity(num_blocks * hash_len);

    for block_num in 1..=num_blocks {
        let mut salt_with_int = salt.to_vec();
        salt_with_int.extend_from_slice(&(block_num as u32).to_be_bytes());

        let u1 = sha1_hmac(password, &salt_with_int);
        let mut block = u1;

        for _ in 1..iterations {
            let u_next = sha1_hmac(password, &block);
            for j in 0..hash_len {
                block[j] ^= u_next[j];
            }
        }

        dk.extend_from_slice(&block);
    }

    dk.truncate(dk_len);
    dk
}
