    k.resize(64, 0);

    let ipad: Vec<u8> = k.iter().map(|&b| b ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|&b| b ^ 0x5C).collect();

    let mut inner = ipad;
    inner.extend_from_slice(data);
    let inner_hash = sha1_hash(&inner);

    let mut outer = opad;
    outer.extend_from_slice(&inner_hash);
    sha1_hash(&outer)
}
