use std::fs;
use std::io::{self, BufRead};
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Instant;
use std::thread;

mod zip_parser;
mod zipcrypto;
mod aes_zip;
mod password_gen;
mod args;

use zip_parser::{parse_zip, ZipEntryInfo, EncryptionType};
