fn format_duration(d: std::time::Duration) -> String {
    let total_ns = d.as_nanos();

    let secs = total_ns / 1_000_000_000;
    let rem = total_ns % 1_000_000_000;
    let ms = rem / 1_000_000;
    let rem = rem % 1_000_000;
    let us = rem / 1_000;
    let ns = rem % 1_000;

    let mut parts = Vec::new();
    if secs > 0 { parts.push(format!("{}s", secs)); }
    if ms > 0 { parts.push(format!("{}ms", ms)); }
    if us > 0 { parts.push(format!("{}us", us)); }
    if ns > 0 { parts.push(format!("{}ns", ns)); }
    if parts.is_empty() { parts.push("0ns".to_string()); }

    parts.join(" ")
}

fn check_password(entry: &ZipEntryInfo, password: &[u8]) -> bool {
    match &entry.encryption {
        EncryptionType::ZipCrypto { crc32, mod_time_byte, use_mod_time, compress_method, .. } => {
            zipcrypto::check_password(
                password,
                &entry.encrypted_data,
                *crc32,
                *mod_time_byte,
                *use_mod_time,
                *compress_method,
            )
        }
        EncryptionType::AesWinzip { aes_strength, salt, pwd_verifier } => {
            aes_zip::check_password(password, salt, pwd_verifier, *aes_strength)
        }
    }
}

